window.ToyData.register("exercises-chemistry.json","[{\"type\":\"choice\",\"prompt\":\"下列变化中，属于化学变化的是（  ）\",\"answer\":\"C\",\"choices\":[{\"key\":\"A\",\"text\":\"冰融化成水\"},{\"key\":\"B\",\"text\":\"铁水铸成锅\"},{\"key\":\"C\",\"text\":\"木柴燃烧\"},{\"key\":\"D\",\"text\":\"胆矾研碎成粉末\"}],\"sourceAnswer\":\"C\",\"explanation\":\"化学变化的特征是有新物质生成。冰融化成水、铁水铸成锅、胆矾研碎都没有生成新物质，属于物理变化；木柴燃烧生成二氧化碳和水等新物质，属于化学变化。\",\"id\":\"cnc_k9acpt3_q127001\",\"topicId\":\"cnc_k9acpt3\",\"linkedTopicIds\":[\"cnc_k9acpt3\",\"cnc_k9acpt4\",\"cnc_k9askl2\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe1\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"用量筒量取液体体积时，下列读数方法正确的是（   ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"把量筒斜拿在手中，从上往下俯视凹液面读数\"},{\"key\":\"B\",\"text\":\"把量筒放在平桌上，视线与凹液面最低处保持水平读数\"},{\"key\":\"C\",\"text\":\"把量筒放在平桌上，从下往上仰视凹液面最高处读数\"},{\"key\":\"D\",\"text\":\"手持量筒，使视线与凹液面最低处保持水平读数\"}],\"sourceAnswer\":\"B\",\"explanation\":\"教材指出“量液时，量筒必须放平，视线要与量筒内液体凹液面的最低处保持水平，再读出液体的体积”，因此必须将量筒放平在桌面上且视线与凹液面最低处水平，选B。\",\"id\":\"cnc_k9acpt45_q127005\",\"topicId\":\"cnc_k9acpt45\",\"linkedTopicIds\":[\"cnc_k9acpt45\",\"cnc_k9askl13\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe5\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列各物质中，属于纯净物的是（  ）\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"空气\"},{\"key\":\"B\",\"text\":\"氧气\"},{\"key\":\"C\",\"text\":\"稀有气体混合物\"},{\"key\":\"D\",\"text\":\"雾霾空气\"}],\"sourceAnswer\":\"B\",\"explanation\":\"纯净物由一种物质组成；混合物由两种或多种物质组成。空气、稀有气体混合物和雾霾空气都含有多种成分，属于混合物；氧气由同一种分子O2组成，是纯净物。\",\"id\":\"cnc_k9acpt64_q127007\",\"topicId\":\"cnc_k9acpt64\",\"linkedTopicIds\":[\"cnc_k9acpt64\",\"cnc_k9acpt65\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe7\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"在原子里质子数等于（ ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"中子数\"},{\"key\":\"B\",\"text\":\"电子数\"},{\"key\":\"C\",\"text\":\"中子数和电子数之和\"},{\"key\":\"D\",\"text\":\"中子数和电子数之差\"}],\"sourceAnswer\":\"B\",\"explanation\":\"电中性原子中，原子核所带的正电荷数与核外电子所带的负电荷数相等，因此质子数=电子数。\",\"id\":\"cnc_k9acpt160_q127024\",\"topicId\":\"cnc_k9acpt160\",\"linkedTopicIds\":[\"cnc_k9acpt160\",\"cnc_k9acpt161\",\"cnc_k9askl37\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe24\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"碳的相对原子质量是（ ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"12 g\"},{\"key\":\"B\",\"text\":\"12\"},{\"key\":\"C\",\"text\":\"1.66×10^-27 kg\"},{\"key\":\"D\",\"text\":\"1/12 g\"}],\"sourceAnswer\":\"B\",\"explanation\":\"相对原子质量是一个比值，没有单位。碳的Ar为12，故选B。12 g和1.66×10^-27 kg是质量值，1/12 g则是碳-12标准的质量定义。\",\"id\":\"cnc_k9acpt173_q127025\",\"topicId\":\"cnc_k9acpt173\",\"linkedTopicIds\":[\"cnc_k9acpt173\",\"cnc_k9acpt175\",\"cnc_k9askl39\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe25\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"已知磷的某种氧化物中磷为+5价，氧为-2价，写出这种磷的氧化物的化学式。\",\"answer\":\"P2O5\",\"explanation\":\"写元素符号P、O，正价写左、负价写右；求两种元素化合价绝对值的最小公倍数10；分别用10除以各元素化合价绝对值得原子数：P为10/5=2，O为10/2=5；得到化学式P2O5；再检查(+5)×2+(-2)×5=0，符合代数和为零原则。\",\"id\":\"cnc_k9askl57_q127036\",\"topicId\":\"cnc_k9askl57\",\"linkedTopicIds\":[\"cnc_k9askl57\",\"cnc_k9acpt264\",\"cnc_k9acpt265\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe36\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"写出铁在氧气中燃烧生成四氧化三铁的化学方程式（注意配平）。\",\"answer\":\"3Fe + 2O2 点燃 Fe3O4\",\"explanation\":\"根据客观事实先写出未配平方程式：Fe + O2 - Fe3O4。再配平：以O为基准，右边O为4个，左边O2分子中O为2个，配2O2；此时右边Fe为3个，左边在Fe前配3，得到 3Fe + 2O2 点燃 Fe3O4。\",\"id\":\"cnc_k9acpt286_q127042\",\"topicId\":\"cnc_k9acpt286\",\"linkedTopicIds\":[\"cnc_k9acpt286\",\"cnc_k9askl63\",\"cnc_k9askl64\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe42\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"加热分解 6.3 g 高锰酸钾，可以得到氧气的质量是多少? (计算结果保留一位小数)\",\"answer\":\"0.6 g 氧气。\",\"explanation\":\"写出反应方程式 2KMnO4 △ K2MnO4 + MnO2 + O2↑。计算 2KMnO4 的相对分子质量为 2×158，与 O2 的 32 成质量比。列式 2×158 : 32 = 6.3 g : x，求得 x≈0.6 g。\",\"id\":\"cnc_k9acpt293_q127043\",\"topicId\":\"cnc_k9acpt293\",\"linkedTopicIds\":[\"cnc_k9acpt293\",\"cnc_k9acpt294\",\"cnc_k9acpt295\",\"cnc_k9askl65\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9a_rjb_exe43\",\"sourceBook\":\"九年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"用1000 t含氧化铁80%的赤铁矿石，理论上可以炼出含铁96%的生铁的质量是多少？\",\"answer\":\"583 t。\",\"explanation\":\"先求赤铁矿中Fe2O3的质量：1000 t×80% = 800 t。由反应Fe2O3 + 3CO = 2Fe + 3CO2，160份Fe2O3生成2×56=112份Fe。设800 t Fe2O3可得x t Fe，有160:112 = 800:x，得x=560 t Fe。生铁含Fe 96%，生铁质量=560 t ÷96% ≈ 583 t。\",\"id\":\"cnc_k9bcpt51_q128004\",\"topicId\":\"cnc_k9bcpt51\",\"linkedTopicIds\":[\"cnc_k9bcpt51\",\"cnc_k9bcpt53\",\"cnc_k9bskl6\",\"cnc_k9bskl7\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe4\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"通过实验回答，铁钉在下列哪些情况下容易生锈？\\n(1)在干燥的空气中；\\n(2)在潮湿的空气中；\\n(3)部分浸入食盐水中；\\n(4)浸没在植物油中。\",\"answer\":\"容易生锈的是(2)在潮湿的空气中和(3)部分浸入食盐水中。\",\"explanation\":\"铁锈蚀需要同时有空气和水。干燥空气中缺水，不易生锈；浸没在植物油中与空气和水隔绝，不易生锈；潮湿空气和部分浸入食盐水时，铁同时接触水和空气，且电解质存在会加快锈蚀。\",\"id\":\"cnc_k9bcpt55_q128005\",\"topicId\":\"cnc_k9bcpt55\",\"linkedTopicIds\":[\"cnc_k9bcpt55\",\"cnc_k9bcpt56\",\"cnc_k9bskl8\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe5\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在农业生产上，常需要用质量分数为 16% 的氯化钠溶液选种。现要配制 150 kg 这种溶液，需要氯化钠和水的质量各是多少？\",\"answer\":\"氯化钠的质量是 24 kg，水的质量是 126 kg。\",\"explanation\":\"由溶质的质量分数 = (溶质质量 / 溶液质量) × 100%。设溶质质量为 m，则 16% = m / 150 × 100%，m = 150 × 16% = 24 kg。溶剂（水）质量 = 溶液质量 - 溶质质量 = 150 - 24 = 126 kg。\",\"id\":\"cnc_k9bcpt120_q128011\",\"topicId\":\"cnc_k9bcpt120\",\"linkedTopicIds\":[\"cnc_k9bcpt120\",\"cnc_k9bcpt123\",\"cnc_k9bskl23\",\"cnc_k9bskl24\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe11\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"化学实验室现有质量分数为 98% 的浓硫酸，但在实验中常需要用较稀的硫酸。要把 50 g 上述浓硫酸稀释为质量分数为 20% 的硫酸，需要水的质量是多少？\",\"answer\":\"需要水的质量为 195 g。\",\"explanation\":\"稀释前后溶质质量不变。设稀释后溶液质量为 x，则 50 g × 98% = x × 20%，解得 x = 245 g。需要加入水的质量 = 245 g - 50 g = 195 g。\",\"id\":\"cnc_k9bcpt120_q128012\",\"topicId\":\"cnc_k9bcpt120\",\"linkedTopicIds\":[\"cnc_k9bcpt120\",\"cnc_k9bcpt126\",\"cnc_k9bskl25\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe12\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"要配制50 g质量分数为6%的氯化钠溶液，需要氯化钠和水各多少克？\",\"answer\":\"溶质质量：50 g×6%=3.0 g氯化钠；溶剂质量：50 g−3.0 g=47.0 g水。\",\"explanation\":\"根据溶质质量分数定义ω(溶质)=m(溶质)/m(溶液)×100%，所以m(溶质)=ω×m(溶液)=6%×50 g=3 g，再用总质量减去溶质质量得到水的质量：50−3=47 g。\",\"id\":\"cnc_034_q128013\",\"topicId\":\"cnc_034\",\"linkedTopicIds\":[\"cnc_034\",\"cnc_k9bskl26\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe13\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"怎样鉴别石灰水和氢氧化钠溶液？\",\"answer\":\"可通入少量二氧化碳：澄清石灰水遇CO₂会生成白色碳酸钙沉淀而变浑浊；氢氧化钠溶液则不立即出现白色沉淀，可据此鉴别两种溶液。\",\"explanation\":\"本题利用氢氧化钙与CO₂反应生成难溶的CaCO₃沉淀，而NaOH与CO₂反应生成易溶的Na₂CO₃，没有明显沉淀现象，所以观察浑浊即可区分石灰水和NaOH溶液。\",\"id\":\"cnc_k9bcpt152_q128015\",\"topicId\":\"cnc_k9bcpt152\",\"linkedTopicIds\":[\"cnc_k9bcpt152\",\"cnc_k9bcpt149\",\"cnc_k9bskl29\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe15\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"厕所用清洁剂中含有盐酸，如果不慎洒到大理石地面上，会发出嘶嘶声，并有气体产生。这种气体是（ ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"二氧化硫\"},{\"key\":\"B\",\"text\":\"二氧化碳\"},{\"key\":\"C\",\"text\":\"氢气\"},{\"key\":\"D\",\"text\":\"氧气\"}],\"sourceAnswer\":\"B\",\"explanation\":\"大理石主要成分是碳酸钙，盐酸与碳酸钙反应生成CO₂和水及钙盐，反应放出二氧化碳产生嘶嘶声，故选B。\",\"id\":\"cnc_k9bcpt156_q128016\",\"topicId\":\"cnc_k9bcpt156\",\"linkedTopicIds\":[\"cnc_k9bcpt156\",\"cnc_k9bcpt134\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe16\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"写出氢氧化钠与盐酸发生中和反应的化学方程式，并指出该反应的基本特征。\",\"answer\":\"化学方程式：NaOH + HCl = NaCl + H2O。基本特征：酸与碱作用，生成盐和水，是中和反应。\",\"explanation\":\"本题要求学生根据课文给出的示例方程式进行书写，并结合定义指出中和反应的核心特征：反应物是酸和碱，生成物是盐和水。\",\"id\":\"cnc_k9bcpt161_q128018\",\"topicId\":\"cnc_k9bcpt161\",\"linkedTopicIds\":[\"cnc_k9bcpt161\",\"cnc_k9bskl35\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe18\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"某溶液的pH为3，判断该溶液属于酸性、碱性还是中性，并说明判断依据。\",\"answer\":\"该溶液为酸性溶液。依据：酸性溶液的pH<7，pH=3小于7。\",\"explanation\":\"考察学生根据pH数值判断酸碱性的能力，直接应用pH与酸、碱、中性的对应关系。\",\"id\":\"cnc_k9bcpt166_q128019\",\"topicId\":\"cnc_k9bcpt166\",\"linkedTopicIds\":[\"cnc_k9bcpt166\",\"cnc_k9bskl33\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe19\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"草木灰是农家肥料, 它的主要成分是一种含钾的盐。取一些草木灰加入盐酸中, 生成的气体可使澄清石灰水变浑浊, 由此可推断草木灰的主要成分可能是________。\",\"answer\":\"碳酸钾\",\"explanation\":\"草木灰主要是含钾的盐；与盐酸反应生成能使澄清石灰水变浑浊的气体，该气体应为 CO2，因此该含钾盐应为碳酸钾：K2CO3 + 2HCl → 2KCl + H2O + CO2↑。\",\"id\":\"cnc_k9bcpt235_q128025\",\"topicId\":\"cnc_k9bcpt235\",\"linkedTopicIds\":[\"cnc_k9bcpt235\",\"cnc_k9bcpt237\",\"cnc_k9bskl47\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_9b_rjb_exe25\",\"sourceBook\":\"九年级下册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"3. 下列关于钠的叙述中，不正确的是（ ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"钠燃烧时发出黄色的火焰\"},{\"key\":\"B\",\"text\":\"钠燃烧时生成氧化钠\"},{\"key\":\"C\",\"text\":\"钠具有很强的还原性\"},{\"key\":\"D\",\"text\":\"钠原子的最外电子层上只有1个电子\"}],\"sourceAnswer\":\"B\",\"explanation\":\"教材指出，钠在空气中加热发出黄色火焰，主要生成过氧化钠Na2O2，故B项说法不符。本节中明确说明钠具有很强还原性，且最外层只有1个电子。\",\"id\":\"cnc_kbx1cpt54_q131006\",\"topicId\":\"cnc_kbx1cpt54\",\"linkedTopicIds\":[\"cnc_kbx1cpt54\",\"cnc_kbx1cpt48\",\"cnc_kbx1cpt51\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe6\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"4. 下列物质放置在空气中，因发生氧化还原反应而变质的是（ ）。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"Na\"},{\"key\":\"B\",\"text\":\"NaOH\"},{\"key\":\"C\",\"text\":\"NaCl\"},{\"key\":\"D\",\"text\":\"Na2CO3\"}],\"sourceAnswer\":\"A\",\"explanation\":\"钠在空气中与氧气发生氧化还原反应生成氧化物，表面变暗，其余NaOH、NaCl、Na2CO3在空气中较稳定，不是因为明显的氧化还原反应而变质。\",\"id\":\"cnc_kbx1cpt50_q131007\",\"topicId\":\"cnc_kbx1cpt50\",\"linkedTopicIds\":[\"cnc_kbx1cpt50\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe7\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"6.(2) 预测: 从物质的类别来看，Na2CO3属于________类，可以与________等类别的物质发生反应。\",\"answer\":\"Na2CO3属于盐类，可以与酸、可溶性钙盐等发生反应。\",\"explanation\":\"碳酸钠是由金属阳离子和酸根组成的盐。探究中设计了与稀盐酸、CaCl2溶液、澄清石灰水等的反应，体现可与酸和某些盐（含Ca2+）反应。\",\"id\":\"cnc_k9bcpt199_q131009\",\"topicId\":\"cnc_k9bcpt199\",\"linkedTopicIds\":[\"cnc_k9bcpt199\",\"cnc_kbx1skl19\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe9\",\"sourceBook\":\"必修一\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"26.5 g Na2CO3 的物质的量是多少？\",\"answer\":\"0.25 mol\",\"explanation\":\"先求 Na2CO3 的摩尔质量 M = 106 g/mol。根据 n = m / M，有 n(Na2CO3) = 26.5 g / (106 g·mol^-1) = 0.25 mol。\",\"id\":\"cnc_kbx1cpt115_q131013\",\"topicId\":\"cnc_kbx1cpt115\",\"linkedTopicIds\":[\"cnc_kbx1cpt115\",\"cnc_kbx1cpt112\",\"cnc_kbx1skl25\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe13\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"配制 500 mL 0.1 mol/L NaOH 溶液，需要 NaOH 的质量是多少？\",\"answer\":\"2 g\",\"explanation\":\"由 c = n / V 得 n(NaOH) = c·V = 0.1 mol/L × 0.5 L = 0.05 mol。NaOH 的摩尔质量为 40 g/mol，则 m = n·M = 0.05 mol × 40 g/mol = 2 g。\",\"id\":\"cnc_kbx1cpt116_q131014\",\"topicId\":\"cnc_kbx1cpt116\",\"linkedTopicIds\":[\"cnc_kbx1cpt116\",\"cnc_kbx1cpt115\",\"cnc_kbx1skl26\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe14\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"3. 下列物质中，在一定条件下与铁反应，且铁元素的化合价能变为+3价的是（ ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"氯化铁溶液\"},{\"key\":\"B\",\"text\":\"氯气\"},{\"key\":\"C\",\"text\":\"硫酸铜溶液\"},{\"key\":\"D\",\"text\":\"稀盐酸\"}],\"sourceAnswer\":\"B\",\"explanation\":\"要使铁从0价变为+3价，需要较强氧化剂。氯气可将Fe氧化为FeCl3；Fe与FeCl3溶液反应生成Fe2+；CuSO4和稀盐酸一般将铁氧化为+2价。\",\"id\":\"cnc_kbx1cpt138_q131017\",\"topicId\":\"cnc_kbx1cpt138\",\"linkedTopicIds\":[\"cnc_kbx1cpt138\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe17\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列物质中，只含有非极性共价键的是（ ）。\",\"answer\":\"C\",\"choices\":[{\"key\":\"A\",\"text\":\"NaOH\"},{\"key\":\"B\",\"text\":\"NaCl\"},{\"key\":\"C\",\"text\":\"H2\"},{\"key\":\"D\",\"text\":\"H2S\"}],\"sourceAnswer\":\"C\",\"explanation\":\"非极性共价键要求由同种原子形成且共用电子对不偏向任何一方。H2 中的 H—H 为非极性共价键；NaOH 和 NaCl 中含离子键，H2S 为极性共价键，因此只有 H2 全部为非极性键。\",\"id\":\"cnc_kbx1cpt239_q131028\",\"topicId\":\"cnc_kbx1cpt239\",\"linkedTopicIds\":[\"cnc_kbx1cpt239\",\"cnc_kbx1skl49\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe28\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列物质中，含有极性共价键的是（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"单质碘\"},{\"key\":\"B\",\"text\":\"氯化镁\"},{\"key\":\"C\",\"text\":\"溴化钾\"},{\"key\":\"D\",\"text\":\"水\"}],\"sourceAnswer\":\"D\",\"explanation\":\"单质碘 I2 中为非极性共价键；MgCl2 和 KBr 为离子化合物，以离子键为主；水分子中 O—H 键为极性共价键，因此答案是 D。\",\"id\":\"cnc_kbx1cpt240_q131029\",\"topicId\":\"cnc_kbx1cpt240\",\"linkedTopicIds\":[\"cnc_kbx1cpt240\",\"cnc_kbx1skl49\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx1_rjb_exe29\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列物质中的硫元素不能表现出氧化性的是（ ）。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"Na2S\"},{\"key\":\"B\",\"text\":\"S\"},{\"key\":\"C\",\"text\":\"SO2\"},{\"key\":\"D\",\"text\":\"H2SO4\"}],\"sourceAnswer\":\"A\",\"explanation\":\"氧化性是指物质能作氧化剂、使他物失电子。硫处于较高正化合价时（如SO2中+4，H2SO4中+6）易得电子而显氧化性；单质硫（0价）既可被氧化也可被还原可表现氧化性；Na2S中S为-2价，处于最低价，一般只能失去还原性、不能再显氧化性。\",\"id\":\"cnc_kbx2cpt20_q132001\",\"topicId\":\"cnc_kbx2cpt20\",\"linkedTopicIds\":[\"cnc_kbx2cpt20\",\"cnc_kbx2skl3\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe1\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列关于SO2的叙述正确的是（ ）。\",\"answer\":\"C\",\"choices\":[{\"key\":\"A\",\"text\":\"SO2是无色、无臭、有毒的气体\"},{\"key\":\"B\",\"text\":\"SO2与NaOH溶液反应生成Na2SO4\"},{\"key\":\"C\",\"text\":\"SO2能使紫色的KMnO4溶液褪色\"},{\"key\":\"D\",\"text\":\"SO2有毒，不能用作食品添加剂\"}],\"sourceAnswer\":\"C\",\"explanation\":\"A错误：SO2有刺激性气味而非无臭；B不全面，SO2与NaOH反应先生成NaHSO3或Na2SO3，不直接生成Na2SO4；C正确，SO2具有还原性，能还原酸性KMnO4使其褪色；D错误，SO2虽有毒但在限量下可用作食品添加剂，教材已举例说明。\",\"id\":\"cnc_kbx2cpt4_q132002\",\"topicId\":\"cnc_kbx2cpt4\",\"linkedTopicIds\":[\"cnc_kbx2cpt4\",\"cnc_kbx2cpt23\",\"cnc_kbx2skl4\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe2\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"在 NO₂ 与水的反应中，（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"氮元素的化合价不发生变化\"},{\"key\":\"B\",\"text\":\"NO₂ 只是氧化剂\"},{\"key\":\"C\",\"text\":\"NO₂ 只是还原剂\"},{\"key\":\"D\",\"text\":\"NO₂ 既是氧化剂，又是还原剂\"}],\"sourceAnswer\":\"D\",\"explanation\":\"3NO₂+H₂O=2HNO₃+NO中，部分NO₂中氮由+4升至+5（作还原剂的氧化对象），部分由+4降至+2（作氧化剂），因此NO₂既是氧化剂又是还原剂。\",\"id\":\"cnc_kbx2cpt33_q132005\",\"topicId\":\"cnc_kbx2cpt33\",\"linkedTopicIds\":[\"cnc_kbx2cpt33\",\"cnc_kbx2skl11\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe5\",\"sourceBook\":\"必修二\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"通过测定某次降雨的pH值为4.5，判断该次降雨是否为酸雨，并说明理由。\",\"answer\":\"该次降雨是酸雨。理由：正常雨水因溶解CO₂，pH约为5.6，而酸雨的pH小于5.6，此次降雨pH=4.5，小于5.6，属于酸雨。\",\"explanation\":\"直接运用“酸雨的pH小于5.6”的判定标准进行判断，体现用pH判断酸雨的技能。\",\"id\":\"cnc_kbx2cpt46_q132007\",\"topicId\":\"cnc_kbx2cpt46\",\"linkedTopicIds\":[\"cnc_kbx2cpt46\",\"cnc_kbx2skl8\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe7\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"1. 下列叙述错误的是（ ）。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"硅在自然界中主要以单质形式存在\"},{\"key\":\"B\",\"text\":\"硅是应用最广泛的半导体材料\"},{\"key\":\"C\",\"text\":\"高纯度的硅可用于制造计算机芯片\"},{\"key\":\"D\",\"text\":\"二氧化硅可用于生产玻璃\"}],\"sourceAnswer\":\"A\",\"explanation\":\"硅在自然界主要以硅酸盐和氧化物形式存在，而不是单质形式，A 错；教材指出硅是应用最广泛的半导体材料，高纯硅用于制造计算机芯片，二氧化硅可用于生产玻璃，因此 B、C、D 正确。\",\"id\":\"cnc_kbx2cpt59_q132008\",\"topicId\":\"cnc_kbx2cpt59\",\"linkedTopicIds\":[\"cnc_kbx2cpt59\",\"cnc_kbx2cpt60\",\"cnc_kbx2cpt74\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe8\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列物质不能用作食品添加剂的是（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"氯化镁\"},{\"key\":\"B\",\"text\":\"亚硝酸钠\"},{\"key\":\"C\",\"text\":\"山梨酸钾\"},{\"key\":\"D\",\"text\":\"三聚氰胺\"}],\"sourceAnswer\":\"D\",\"explanation\":\"氯化镁可作为豆腐制作中的凝固剂；亚硝酸钠在严格限量下可作为防腐剂和护色剂；山梨酸钾是常见防腐剂。三聚氰胺不能作为食品添加剂，违规添加会严重危害健康。\",\"id\":\"cnc_kbx2cpt326_q132036\",\"topicId\":\"cnc_kbx2cpt326\",\"linkedTopicIds\":[\"cnc_kbx2cpt326\",\"cnc_kbx2cpt334\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe36\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"工业废渣和生活垃圾等固体废物的处理应遵循哪些原则？这些原则的共同目标是什么？\",\"answer\":\"应遵循无害化、减量化和资源化的原则；共同目标是减少环境污染并实现资源回收利用。\",\"explanation\":\"本题考查对教材原文中固体废物处理原则的理解和记忆。先准确写出三个关键词“无害化、减量化、资源化”，再结合文本说明其核心目标是既减少环境污染又回收利用资源。\",\"id\":\"cnc_kbx2cpt355_q132040\",\"topicId\":\"cnc_kbx2cpt355\",\"linkedTopicIds\":[\"cnc_kbx2cpt355\",\"cnc_kbx2cpt356\",\"cnc_kbx2cpt357\",\"cnc_kbx2cpt358\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_bx2_rjb_exe40\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列说法中正确的是（   ）\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"只有放热反应才能自发进行\"},{\"key\":\"B\",\"text\":\"只有熵增的化学反应才能自发进行\"},{\"key\":\"C\",\"text\":\"自发反应的方向只取决于焓变\"},{\"key\":\"D\",\"text\":\"自发反应的方向与焓变和熵变都有关，二者都不能单独作为判断依据\"}],\"sourceAnswer\":\"D\",\"explanation\":\"教材指出“大多数放热反应是可以自发进行的……有些吸热反应也可以自发进行”，说明并非只有放热反应才能自发；同时“有些熵减的过程也能自发进行”，说明并非只有熵增才能自发。结论是“自发反应的方向与焓变和熵变有关，但焓变和熵变又都不能单独作为判断反应自发进行方向的依据”，故选D。\",\"id\":\"cnc_kxzxbx1cpt59_q141009\",\"topicId\":\"cnc_kxzxbx1cpt59\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt59\",\"cnc_kxzxbx1cpt7\",\"cnc_kxzxbx1cpt61\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe9\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"在等温、等压条件下，下列哪种情况下反应一定能自发进行？（   ）\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"ΔH>0，ΔS<0\"},{\"key\":\"B\",\"text\":\"ΔH<0，ΔS<0\"},{\"key\":\"C\",\"text\":\"ΔH>0，ΔS>0\"},{\"key\":\"D\",\"text\":\"ΔH<0，ΔS>0\"}],\"sourceAnswer\":\"D\",\"explanation\":\"由ΔG=ΔH−TΔS可知，当ΔH<0且ΔS>0时，无论温度如何，TΔS为正数，−TΔS为负，ΔG一定为负，反应必然自发。教材“由上述关系式可推知：当ΔH<0，ΔS>0时，反应能自发进行；当ΔH>0，ΔS<0时，反应不能自发进行；当ΔH和ΔS同号时自发性与温度有关。”故选D。\",\"id\":\"cnc_kxzxbx1cpt68_q141010\",\"topicId\":\"cnc_kxzxbx1cpt68\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt68\",\"cnc_kxzxbx1cpt69\",\"cnc_kxzxbx1skl19\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe10\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"standard\"},{\"type\":\"choice\",\"prompt\":\"合成氨工业中采用循环操作，主要是为了（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"增大化学反应速率\"},{\"key\":\"B\",\"text\":\"提高平衡混合物中氨的含量\"},{\"key\":\"C\",\"text\":\"降低氨的沸点\"},{\"key\":\"D\",\"text\":\"提高氮气和氢气的利用率\"}],\"sourceAnswer\":\"D\",\"explanation\":\"循环操作的核心目的是使未反应的N₂和H₂重新进入合成塔反应，提高原料气利用率和整体转化率。提高平衡混合物中氨含量依靠改变温度、压强和浓度，而不是循环本身。\",\"id\":\"cnc_kxzxbx1cpt82_q141011\",\"topicId\":\"cnc_kxzxbx1cpt82\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt82\",\"cnc_kxzxbx1cpt73\",\"cnc_kxzxbx1skl25\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe11\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在某温度时，溶质的物质的量浓度为 0.20 mol·L⁻¹ 的氨水中，达到电离平衡时，已电离的 NH3·H2O 为 1.7×10⁻³ mol·L⁻¹。试计算该温度下 NH3·H2O 的电离常数 Kb。\",\"answer\":\"Kb ≈ 1.4×10⁻⁵\",\"explanation\":\"写出电离方程式：NH3·H2O ⇌ NH4⁺ + OH⁻。根据“起始–变化–平衡”列出各粒子浓度：起始 c(NH3·H2O)=0.20 mol·L⁻¹，c(NH4⁺)=0，c(OH⁻)=0；变化：均为 ±1.7×10⁻³；平衡：c(NH3·H2O)=0.20−1.7×10⁻³≈0.20 mol·L⁻¹，c(NH4⁺)=1.7×10⁻³ mol·L⁻¹，c(OH⁻)=1.7×10⁻³ mol·L⁻¹。代入 Kb = c(NH4⁺)·c(OH⁻)/c(NH3·H2O) 得 Kb ≈ (1.7×10⁻³)² / 0.20 ≈ 1.4×10⁻⁵。\",\"id\":\"cnc_kxzxbx1cpt112_q141016\",\"topicId\":\"cnc_kxzxbx1cpt112\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt112\",\"cnc_kbx1cpt22\",\"cnc_kxzxbx1skl30\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe16\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"在一定温度下，Mg(OH)2 在水中的沉淀溶解平衡可用离子方程式表示为________，该平衡的 Ksp 可表示为________。\",\"answer\":\"Mg(OH)2(s) ⇌ Mg²⁺(aq) + 2OH⁻(aq)；Ksp = c(Mg²⁺)·c(OH⁻)²\",\"explanation\":\"根据 Mg(OH)2 的化学式写出溶解平衡；固体不写入平衡常数表达式，按化学计量系数写浓度幂次。\",\"id\":\"cnc_kxzxbx1cpt168_q141020\",\"topicId\":\"cnc_kxzxbx1cpt168\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt168\",\"cnc_kxzxbx1cpt170\",\"cnc_kxzxbx1skl44\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe20\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"难溶电解质在水中达到沉淀溶解平衡时，下列说法中错误的是（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"沉淀的速率和溶解的速率相等\"},{\"key\":\"B\",\"text\":\"难溶电解质在水中形成饱和溶液\"},{\"key\":\"C\",\"text\":\"再加入难溶电解质, 溶液中各离子的浓度不变\"},{\"key\":\"D\",\"text\":\"难溶电解质溶解形成的阴、阳离子的浓度相等\"}],\"sourceAnswer\":\"D\",\"explanation\":\"平衡时溶解和沉淀速率相等，溶液为饱和，再加固体不改变离子浓度，前三项正确；多价离子和化学计量数不同时，阴、阳离子浓度一般不相等，因此 D 错误。\",\"id\":\"cnc_kxzxbx1cpt168_q141021\",\"topicId\":\"cnc_kxzxbx1cpt168\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt168\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe21\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"4. 下列有关电解的叙述中错误的是（ ）。\",\"answer\":\"C\",\"choices\":[{\"key\":\"A\",\"text\":\"与电源正极相连的是阳极\"},{\"key\":\"B\",\"text\":\"与电源负极相连的是阴极\"},{\"key\":\"C\",\"text\":\"在阴极上发生氧化反应\"},{\"key\":\"D\",\"text\":\"阴离子向阳极方向迁移\"}],\"sourceAnswer\":\"C\",\"explanation\":\"电解池中与电源正极相连的是阳极，与负极相连的是阴极；阴离子向阳极迁移，阳离子向阴极迁移；阳极上发生氧化反应，阴极上发生还原反应，因此说“在阴极上发生氧化反应”是错误的。\",\"id\":\"cnc_kxzxbx1cpt226_q141029\",\"topicId\":\"cnc_kxzxbx1cpt226\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt226\",\"cnc_kxzxbx1cpt227\",\"cnc_kxzxbx1cpt231\",\"cnc_kxzxbx1cpt228\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe29\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"为了延长锅炉的使用寿命，常在其内壁焊上锌片。请简要说明这种做法所依据的原理。\",\"answer\":\"锌比铁更活泼，将锌片焊在锅炉内壁上时，锌和铁以及锅炉中的电解质溶液构成原电池，锌作为阳极优先被氧化溶解，铁作为阴极基本不被腐蚀，从而起到保护锅炉钢铁内壁的作用。这就是牺牲阳极法的阴极保护原理。\",\"id\":\"cnc_kxzxbx1cpt257_q141032\",\"topicId\":\"cnc_kxzxbx1cpt257\",\"linkedTopicIds\":[\"cnc_kxzxbx1cpt257\",\"cnc_kxzxbx1skl63\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx1_rjb_exe32\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"从电负性角度解释：为什么 NaCl 中形成的是离子键，而 HCl 和 CO 中主要形成的是共价键？请简要说明你的判断依据。\",\"answer\":\"Na 和 Cl 的电负性差很大，Na 容易失去电子而 Cl 容易得电子，电子对不被共用，从而形成离子键；而 H 与 Cl、C 与 O 的电负性虽然不同，但差值没有 Na 与 Cl 那么大，电子对可以在两原子间共用，因此形成的是共价键。\",\"explanation\":\"围绕“电负性差大→电子转移→离子键；电负性差不大→电子共用→共价键”的逻辑，并联系题中给出的 NaCl、HCl、CO 三种物质进行对比说明。\",\"id\":\"cnc_kxzxbx2cpt55_q142005\",\"topicId\":\"cnc_kxzxbx2cpt55\",\"linkedTopicIds\":[\"cnc_kxzxbx2cpt55\",\"cnc_kxzxbx2skl10\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx2_rjb_exe5\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"已知SO₂的中心原子为S，S的价电子数为6，与S结合的O的个数为2，每个O原子最多能接受的电子数为2。根据价层电子对互斥模型中的公式：中心原子上的孤电子对数 = ½(a − x b)，求SO₂中S原子上的孤电子对数，并据此判断SO₂分子中S原子周围共有多少个价层电子对。\",\"answer\":\"代入a=6, x=2, b=2，孤电子对数 = ½(6 − 2×2) = ½(2) = 1，对应1对孤电子对；SO₂中S与2个O成键有2个σ键电子对，因此S原子周围共有3对价层电子对。\",\"explanation\":\"本题考查对孤电子对数公式的理解和应用。先根据题意确定a、x、b的值，再代入公式计算孤电子对数。计算得到1对孤电子对。S与两个O成键形成2个σ键电子对，所以总的价层电子对数为1（孤电子对）+2（键电子对）=3对，为进一步用VSEPR预测SO₂形状提供基础。\",\"id\":\"cnc_kxzxbx2cpt88_q142006\",\"topicId\":\"cnc_kxzxbx2cpt88\",\"linkedTopicIds\":[\"cnc_kxzxbx2cpt88\",\"cnc_kxzxbx2skl14\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx2_rjb_exe6\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"甲烷分子CH₄的键角为109°28′，4个C–H单键完全等价。若仅用1个2s轨道和3个相互垂直的2p轨道分别与4个H原子的1s轨道重叠，能否解释这种结构？应采用哪种杂化方式才能合理解释甲烷分子的键角和形状？\",\"answer\":\"不能。2s轨道为球形，3个2p轨道相互垂直，直接用这4个轨道成键不能得到4个方向完全等价且夹角为109°28′的四面体结构。需要采用sp³杂化：碳的1个2s轨道与3个2p轨道杂化形成4个等价的sp³杂化轨道，指向正四面体的4个顶角，从而解释甲烷为正四面体结构、键角为109°28′。\",\"explanation\":\"题干引导学生从“原始s、p轨道形状和方向”与“实验观测到的四面体等价键”之间的矛盾出发，得出必须引入杂化概念。指出sp³杂化的构成及其几何方向性，说明其能自然地给出四面体键角。\",\"id\":\"cnc_kxzxbx2cpt94_q142007\",\"topicId\":\"cnc_kxzxbx2cpt94\",\"linkedTopicIds\":[\"cnc_kxzxbx2cpt94\",\"cnc_kxzxbx2skl15\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx2_rjb_exe7\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"standard\"},{\"type\":\"choice\",\"prompt\":\"下列关于氢键X—H…Y的说法中，错误的是（ ）。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"氢键是共价键的一种\"},{\"key\":\"B\",\"text\":\"同一分子内也可能形成氢键\"},{\"key\":\"C\",\"text\":\"X、Y元素具有很大的电负性, 是氢键形成的基本条件\"},{\"key\":\"D\",\"text\":\"氢键能增大很多物质分子之间的作用力, 导致沸点升高\"}],\"sourceAnswer\":\"A\",\"explanation\":\"教材明确指出氢键与化学键比较，属于较弱的作用力，不属于化学键，因此不是共价键的一种，A错误。B、C、D均与教材对氢键的定义和影响相符。\",\"id\":\"cnc_kbx1cpt246_q142009\",\"topicId\":\"cnc_kbx1cpt246\",\"linkedTopicIds\":[\"cnc_kbx1cpt246\",\"cnc_kxzxbx2cpt106\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx2_rjb_exe9\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"试用电子气理论解释金属具有良好延展性的原因。\",\"answer\":\"在金属晶体中，金属原子价电子脱离原子形成遍布整个晶体的电子气，被所有原子共用。当金属受到外力时，晶体中各原子层可以发生相对滑动而不改变整体的排列方式，弥漫在原子间的电子气起到类似润滑剂的作用，维系原子间的结合，因此金属在外力作用下不易断裂，表现出良好的延展性。\",\"explanation\":\"本题考查学生对电子气理论的理解和其对金属宏观力学性质解释的能力。答题关键是指出：1) 金属晶体中的价电子形成电子气并被共有；2) 外力作用只导致原子层相对滑动而不破坏整体配位结构；3) 电子气起润滑作用，保证滑动过程金属键未整体断裂，从而体现延展性。\",\"id\":\"cnc_kxzxbx2cpt181_q142017\",\"topicId\":\"cnc_kxzxbx2cpt181\",\"linkedTopicIds\":[\"cnc_kxzxbx2cpt181\",\"cnc_k9bcpt8\",\"cnc_kxzxbx2skl28\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx2_rjb_exe17\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"NaCl 和 CsCl 都是离子晶体，它们为什么具有较高的熔点和沸点？\",\"answer\":\"在 NaCl 和 CsCl 晶体中，阳离子和阴离子之间存在较强的离子键作用，使晶体硬度大、难以压缩。要使它们由固态变成液态或气态，必须提供足够能量来破坏这些强的离子键，因此 NaCl 和 CsCl 的熔点和沸点都较高。\",\"explanation\":\"本题要求从微观作用力角度解释宏观熔沸点。应说明：离子晶体中带反电荷的离子间存在强静电作用，形成强离子键；熔化和汽化需要克服这种作用力，所以熔沸点高。可联系文本提供的具体数值加深理解。\",\"id\":\"cnc_kxzxbx2cpt185_q142018\",\"topicId\":\"cnc_kxzxbx2cpt185\",\"linkedTopicIds\":[\"cnc_kxzxbx2cpt185\",\"cnc_kbx1cpt235\",\"cnc_kxzxbx2cpt186\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx2_rjb_exe18\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"3. 下列反应不属于加成反应的是（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"乙烯水化法合成乙醇\"},{\"key\":\"B\",\"text\":\"乙炔与氯化氢反应\"},{\"key\":\"C\",\"text\":\"1-丁烯使溴的四氯化碳溶液褪色\"},{\"key\":\"D\",\"text\":\"1-丁炔使酸性高锰酸钾溶液褪色\"}],\"sourceAnswer\":\"D\",\"explanation\":\"A、B、C 都是含双键或三键与小分子发生加成反应；D 中 1-丁炔与酸性高锰酸钾反应本质上是氧化反应，褪色不属于加成，因此选 D。\",\"id\":\"cnc_kbx2cpt184_q143007\",\"topicId\":\"cnc_kbx2cpt184\",\"linkedTopicIds\":[\"cnc_kbx2cpt184\",\"cnc_kxzxbx3cpt93\",\"cnc_kxzxbx3skl18\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx3_rjb_exe7\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"standard\"},{\"type\":\"choice\",\"prompt\":\"2. 苯酚具有弱酸性的原因是（ ）。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"羟基使苯环活化\"},{\"key\":\"B\",\"text\":\"苯环使羟基中的 O—H 极性变强\"},{\"key\":\"C\",\"text\":\"苯酚能与 NaOH 溶液反应\"},{\"key\":\"D\",\"text\":\"苯酚能与溴水反应\"}],\"sourceAnswer\":\"B\",\"explanation\":\"弱酸性的本质原因是苯环与羟基相互作用，使 O—H 键极性增强、H 更易电离，即选 B；与 NaOH、溴水反应是性质表现或相关结果，不是根本原因。\",\"id\":\"cnc_kxzxbx3cpt178_q143014\",\"topicId\":\"cnc_kxzxbx3cpt178\",\"linkedTopicIds\":[\"cnc_kxzxbx3cpt178\",\"cnc_kxzxbx3cpt181\",\"cnc_kxzxbx3skl33\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx3_rjb_exe14\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列关于油脂的叙述不正确的是（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"油脂属于酯类\"},{\"key\":\"B\",\"text\":\"油脂没有固定的熔点和沸点\"},{\"key\":\"C\",\"text\":\"油脂是高级脂肪酸的甘油酯\"},{\"key\":\"D\",\"text\":\"油脂都不能使溴水褪色\"}],\"sourceAnswer\":\"D\",\"explanation\":\"天然油脂往往含有不饱和脂肪酸酯，能与溴加成使溴水褪色，因此“都不能使溴水褪色”错误。A、C符合定义，B是因为油脂为混合物，一般无固定熔沸点。\",\"id\":\"cnc_k9bcpt252_q143020\",\"topicId\":\"cnc_k9bcpt252\",\"linkedTopicIds\":[\"cnc_k9bcpt252\",\"cnc_kxzxbx3cpt27\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx3_rjb_exe20\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"下列哪种元素不是蛋白质的主要组成元素（ ）。\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"碳\"},{\"key\":\"B\",\"text\":\"氢\"},{\"key\":\"C\",\"text\":\"氮\"},{\"key\":\"D\",\"text\":\"氯\"}],\"sourceAnswer\":\"D\",\"explanation\":\"教材指出蛋白质主要由C、H、O、N、S等元素组成，氯不在主要元素之列。\",\"id\":\"cnc_kxzxbx3cpt300_q143033\",\"topicId\":\"cnc_kxzxbx3cpt300\",\"linkedTopicIds\":[\"cnc_kxzxbx3cpt300\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx3_rjb_exe33\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"蛋白质的（ ）与肽键的形成有关。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"一级结构\"},{\"key\":\"B\",\"text\":\"二级结构\"},{\"key\":\"C\",\"text\":\"三级结构\"},{\"key\":\"D\",\"text\":\"四级结构\"}],\"sourceAnswer\":\"A\",\"explanation\":\"肽键连接氨基酸形成多肽链，决定氨基酸的排列顺序，即蛋白质的一级结构。二级、三级、四级结构更多由氢键和非共价相互作用维持。\",\"id\":\"cnc_kxzxbx3cpt301_q143034\",\"topicId\":\"cnc_kxzxbx3cpt301\",\"linkedTopicIds\":[\"cnc_kxzxbx3cpt301\",\"cnc_kxzxbx3cpt298\"],\"source\":\"k12-exercise\",\"sourceId\":\"chemistry_xzxbx3_rjb_exe34\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"}]");
